/**
 * The TypeScript script demo boxes in the browser (Output blocks generated by scripts/ts-script-demos.ts).
 *
 * - /build-scripts#typescript: the Preview is the docs page running the same TypeScript build script, so its trail
 *   names this page, and the Output (a temp site's page at the same path) shows the same trail.
 * - /scoped-javascript: the Preview is this page's own `.ts` file, compiled and inlined; it runs under the page's
 *   Content-Security-Policy and counts clicks.
 * - /server-scripts#typescript, /stream-scripts#typescript, /configuration#scriptstypescript: no Preview (a static
 *   site runs no server or stream script, and the docs use the default compiler); the Output shows what the real
 *   server or esbuild produced.
 */
import { test, expect, type Locator, type Page } from "@playwright/test";

/** The first demo box after the heading with `id`. */
const boxAfter = (page: Page, id: string): Locator =>
  page.locator(`#${id} ~ *:has([data-testid="demo-pane-code"])`).first();

const showOutput = async (box: Locator): Promise<Locator> => {
  await box.getByTestId("demo-tab-output").click();
  return box.locator('[data-pane="output"]');
};

test("the TypeScript build script's Preview and Output show the same page trail", async ({
  page,
}) => {
  await page.goto("/build-scripts");
  const box = boxAfter(page, "typescript");
  const preview = box.getByTestId("demo-pane-preview");
  await expect(
    preview.getByRole("navigation", { name: "Breadcrumb" }),
  ).toHaveText("Home / build-scripts");
  const output = await showOutput(box);
  await expect(output).toContainText(
    '<nav aria-label="Breadcrumb">Home / build-scripts</nav>',
  );
  await expect(output).not.toContainText(": string");
});

test("a page's own .ts file runs in the Preview under the page's CSP", async ({
  page,
}) => {
  const violations: string[] = [];
  page.on("console", (message) => {
    if (/Content Security Policy|Content-Security-Policy/i.test(message.text()))
      violations.push(message.text());
  });
  await page.goto("/scoped-javascript");
  const box = boxAfter(page, "example-a-pages-own-typescript-file");
  const button = box.getByTestId("page-counter");
  await expect(button).toHaveText("Clicked 0 times");
  await button.click();
  await button.click();
  await expect(button).toHaveText("Clicked 2 times");
  expect(violations).toEqual([]);
  const output = await showOutput(box);
  await expect(output).toContainText("//# sourceURL=src/pages/counter.ts");
  await expect(output).not.toContainText("HTMLButtonElement");
});

for (const { path, id, text } of [
  { path: "/server-scripts", id: "typescript", text: "<p>Hello, Ada</p>" },
  {
    path: "/stream-scripts",
    id: "typescript",
    text: "<li>Milk frother: 3 left</li>",
  },
  {
    path: "/configuration",
    id: "scriptstypescript",
    text: "((Size2) => {",
  },
]) {
  test(`${path}#${id}: no Preview, and the Output shows the real result`, async ({
    page,
  }) => {
    await page.goto(path);
    const box = boxAfter(page, id);
    await expect(box.getByTestId("demo-tab-preview")).toBeHidden();
    const output = await showOutput(box);
    await expect(output).toContainText(text);
  });
}
